// src/Navbar.js
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";

const Navbar = () => {
  const navigate = useNavigate();

  return (
    <motion.nav
      initial={{ y: -40, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.7, ease: "easeOut" }}
      className="fixed top-0 left-0 w-full bg-black shadow-md border-b border-gray-800 z-50"
    >
      <div className="max-w-7xl mx-auto px-8 py-4 flex items-center justify-between">
        {/* Logo */}
        <motion.h1
          className="text-2xl md:text-3xl font-serif font-bold text-white select-none cursor-pointer"
          whileHover={{ scale: 1.05 }}
          onClick={() => navigate("/")}
        >
          AI Interview Coach
        </motion.h1>

        {/* Navigation links (optional) */}
        <div className="hidden md:flex gap-8 text-white font-medium">
          <button onClick={() => navigate("/home")} className="hover:text-indigo-400 transition">Home</button>
          <button onClick={() => navigate("/practice")} className="hover:text-indigo-400 transition">Practice</button>
          <button onClick={() => navigate("/interview")} className="hover:text-indigo-400 transition">Interview</button>
          <button onClick={() => navigate("/feedback")} className="hover:text-indigo-400 transition">Feedback</button>
          <button onClick={() => navigate("/login")} className="hover:text-indigo-400 transition">Login</button>
        </div>
      </div>
    </motion.nav>
  );
};

export default Navbar;
